using ClipBridge;
using System.Security.Cryptography;
using System.Text.Json;
void Check(bool b,string name){if(!b)throw new Exception(name);Console.WriteLine("PASS "+name);}
void Reject(Action f,string name){try{f();}catch(Exception e)when(e is CryptographicException or ArgumentException){Check(true,name);return;}throw new Exception(name);}
string root=args[1];Directory.CreateDirectory(root);string own=Guid.NewGuid().ToString("N"),peer=Guid.NewGuid().ToString("N");var good=WebDavPairing.Create(args[0]+"/dav/base/","dav-user","test-only-password");var bad=WebDavPairing.Create(args[0]+"/bad/","dav-user","test-only-password");
var a=good.Windows;var b=good.Android;string id=Guid.NewGuid().ToString("N");byte[] plain=RandomNumberGenerator.GetBytes(Attachments.ChunkSize);var cipher=Attachments.Encrypt(a,id,0,plain);Check(Attachments.Decrypt(b,id,0,cipher).SequenceEqual(plain),"attachment AES-GCM roundtrip");Reject(()=>Attachments.Decrypt(b,id,1,cipher),"chunk position authenticated");Reject(()=>Attachments.Decrypt(b,id,0,cipher[..^1]),"truncated chunk rejected");var changed=cipher.ToArray();changed[20]^=1;Reject(()=>Attachments.Decrypt(b,id,0,changed),"tampered chunk rejected");Check(Attachments.Decrypt(b,id,0,Attachments.Encrypt(a,id,0,[])).Length==0,"empty file chunk");
Check(DeviceIdentity.Read(b,DeviceIdentity.Seal(a,"Computer",own)).Installation==own,"stable installation identity authenticated");
var profilesA=new List<BridgeProfile>{new(){Config=bad.Windows,PeerIdentity=peer},new(){Config=a,PeerIdentity=peer}};var profilesB=new List<BridgeProfile>{new(){Config=bad.Android,PeerIdentity=own},new(){Config=b,PeerIdentity=own}};Check(profilesA.GroupBy(p=>p.Group).Count()==1,"same device routes form one target");profilesA[0].Enabled=false;Check(profilesA.Count(p=>p.Enabled)==1,"independent profile switch");profilesA[0].Enabled=true;
var sa=new AttachmentState();var sb=new AttachmentState();int requests=0,received=0;var ha=new TransferHub(()=>profilesA,sa,Path.Combine(root,"a"),own,()=>{});var hb=new TransferHub(()=>profilesB,sb,Path.Combine(root,"b"),peer,()=>{});hb.Requested=_=>requests++;hb.Received=async item=>{Check(File.ReadAllBytes(item.Path).SequenceEqual(File.ReadAllBytes(Path.Combine(root,"sample.bin"))),"received file hash and bytes match");received++;await hb.Complete(item,true);};
string path=Path.Combine(root,"sample.bin");File.WriteAllBytes(path,RandomNumberGenerator.GetBytes(Attachments.ChunkSize*2+51));await ha.Stage(path,"file",profilesA.Select(p=>p.Config.Pair).ToList(),CancellationToken.None);await ha.Tick(CancellationToken.None);await hb.Tick(CancellationToken.None);Check(requests==1 && sb.Incoming.Count==1,"one file request across fallback routes");Check(sa.Outgoing[0].Uploaded.Count==0,"no file upload before receiver consent");await ha.Tick(CancellationToken.None);Check(sa.Outgoing[0].Uploaded.Count==0,"waiting does not upload file bytes");await hb.Decide(sb.Incoming[0].Offer.Id,true);await hb.Tick(CancellationToken.None);
for(int i=0;i<8&&received==0;i++){await ha.Tick(CancellationToken.None);await hb.Tick(CancellationToken.None);}Check(received==1,"failed first route automatically switches to working route");await hb.Tick(CancellationToken.None);await ha.Tick(CancellationToken.None);await hb.Tick(CancellationToken.None);Check(received==1&&requests==1,"route retries do not duplicate receive or prompt");
await ha.Stage(path,"file",new(){a.Pair},CancellationToken.None);await ha.Tick(CancellationToken.None);await hb.Tick(CancellationToken.None);var last=sb.Incoming.Last();await hb.Decide(last.Offer.Id,false);await hb.Tick(CancellationToken.None);await ha.Tick(CancellationToken.None);Check(sa.Outgoing.Last().Phase=="rejected"&&sa.Outgoing.Last().Uploaded.Count==0,"receiver decline prevents payload upload");
string huge=Path.Combine(root,"large.bin");using(var f=File.Create(huge))f.SetLength(Attachments.MaxSize+1);try{await ha.Stage(huge,"file",new(){a.Pair},CancellationToken.None);throw new Exception("size accepted");}catch(ArgumentException){Check(true,"100 MB cap checked before staging");}
var chunk=Attachments.Encrypt(a,id,0,System.Text.Encoding.UTF8.GetBytes("interop attachment 中文"));var offer=new AttachmentOffer(id,"example.bin","application/octet-stream","file",0,Convert.ToHexString(SHA256.HashData([])).ToLowerInvariant(),1,DateTimeOffset.UtcNow.ToUnixTimeSeconds()+3600,"offered",own);var index=Attachments.SealIndex(a,new(new(){offer},new()));Check(Attachments.OpenIndex(b,index).Offers.Count==1,"encrypted manifest roundtrip");Reject(()=>Attachments.OpenIndex(b,Attachments.SealIndex(a,new(new(){offer},new()),DateTimeOffset.UtcNow.ToUnixTimeSeconds()-3601)),"expired attachment manifest rejected");
File.WriteAllText(Path.Combine(root,"crypto.json"),JsonSerializer.Serialize(new{sender=a,receiver=b,id,chunk=Convert.ToBase64String(chunk),index},Wire.Json));
